contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);

        uint256 beforeC = address(c).balance;
        uint256 beforeUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 afterC = address(c).balance;
        uint256 afterUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(afterC == beforeC && afterUserBalance == beforeUserBalance);
    }

    receive() external payable {}
}

