pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 beforeC = address(c).balance;
        uint256 beforeUserBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeUserBalance = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        uint256 afterC = address(c).balance;
        uint256 afterUserBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterUserBalance = __r; } catch { return; }
        assertTrue(afterC == beforeC && afterUserBalance == beforeUserBalance);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
